use std::{fs,path::Path,collections::BTreeSet};use serde_json::{Value,json};use sha2::{Sha256,Digest};const R:&str="/home/ubuntu/src/zopro-perf-work/group-admission213";fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);for(p,h)in read(r.join("pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let seed="/home/ubuntu/src/zopro-perf-work/group-input212/proof-sha256-after-audit.json";assert_eq!(hash(seed),"616aa4f0fa5259f893875bad99585b78c71366cbaebc65fc044586c85f7d1a5a");let mut ledger:BTreeSet<String>=serde_json::from_value(read(seed)).unwrap();assert_eq!(ledger.len(),58982);let mut arms=vec![];let mut receipts=0;for j in read(r.join("jobs.json")).as_array().unwrap(){let arm=j["arm"].as_str().unwrap();for name in[format!("capture-{arm}"),format!("verify-{arm}")]{let d=r.join("run").join(name);let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(d.join(format!("{s}.log"))),e[format!("{s}_sha256")]);}receipts+=1;}
let stderr=fs::read_to_string(r.join(format!("run/capture-{arm}/stderr.log"))).unwrap();let records=stderr.lines().filter(|l|l.starts_with("GROUP_ADMISSION ")).map(|l|{let mut f=l.split_whitespace();assert_eq!(f.next(),Some("GROUP_ADMISSION"));let n=f.next().unwrap().strip_prefix("n=").unwrap().parse::<usize>().unwrap();let p=f.next().unwrap().strip_prefix("peak=Some(").unwrap().strip_suffix(')').unwrap().parse::<usize>().unwrap();let admitted=f.next().unwrap().strip_prefix("admitted=").unwrap().parse::<bool>().unwrap();json!({"n":n,"peak":p,"admitted":admitted})}).collect::<Vec<_>>();let g2=records.iter().filter(|v|v["n"]==30089).cloned().collect::<Vec<_>>();assert_eq!(g2.len(),4);let a=records.iter().filter(|v|v["n"]==21006).cloned().collect::<Vec<_>>();assert_eq!(a.len(),4);let workspace=stderr.lines().filter(|l|l.starts_with("TYPED_WORKSPACE ")).collect::<Vec<_>>();assert_eq!(workspace.len(),1);
let out=fs::read_to_string(r.join(format!("run/capture-{arm}/stdout.log"))).unwrap();let s:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(s["rounds"],1);assert_eq!(s["priming"],3);assert_eq!(s["workers"],32);assert_eq!(s["boolean_routes"],if arm=="ON"{json!([0,1,0,0])}else{json!([0,0,0,0])});assert_eq!(s["placement_before"],s["placement_after"]);let pd=Path::new(j["proof_dir"].as_str().unwrap());let ph=hash(pd.join("0.proof"));assert_eq!(fs::metadata(pd.join("0.proof")).unwrap().len(),164);assert_eq!(hash(pd.join("0.public")),j["public_sha256"]);assert!(ledger.insert(ph.clone()));let v=fs::read_to_string(r.join(format!("run/verify-{arm}/stdout.log"))).unwrap();assert!(v.contains(&format!("VERIFIED proof_sha256={ph} ")));arms.push(json!({"arm":arm,"G2":g2,"A":a,"workspace":workspace[0],"proof_sha256":ph}));}
let identical=arms[0]["G2"]==arms[1]["G2"]&&arms[0]["A"]==arms[1]["A"];let path=r.join("proof-sha256-after-audit.json");assert!(!path.exists());fs::write(&path,serde_json::to_vec_pretty(&ledger).unwrap()).unwrap();assert_eq!(ledger.len(),58984);let result=json!({"pass":true,"diagnostic_only":true,"admission_outcomes_equal":identical,"arms":arms,"receipts":receipts,"stream_hashes":receipts*2,"fresh_Gnark_exports":2,"SDK_calls":8,"canonical_count":ledger.len(),"canonical_sha256":hash(path),"no_performance_claim":true});fs::write(r.join("result.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{result}");}
